// Definição dos pinos para os controles
const int PINO_LED = 13;
const int PINO_BOTAO = 2;
const int PINO_SENSOR = A0;

// Variáveis de estado
bool sistemaAtivo = true;
int velocidadeLeitura = 1000; // em milissegundos

void setup() {
  Serial.begin(9600);
  pinMode(PINO_LED, OUTPUT);
  pinMode(PINO_BOTAO, INPUT_PULLUP);

  exibirMenu();
}

void loop() {
  // Verifica se há comandos enviados pelo terminal (Shell)
  if (Serial.available() > 0) {
    char comando = Serial.read();
    processarComando(comando);
  }

  // Executa leituras contínuas se o sistema estiver ativo
  if (sistemaAtivo) {
    // Exemplo de leitura de sensor periódica
    // int valorSensor = analogRead(PINO_SENSOR);
    delay(velocidadeLeitura);
  }
}

void exibirMenu() {
  Serial.println(F("\n====================================="));
  Serial.println(F("    PAINEL DE CONTROLE INTERATIVO     "));
  Serial.println(F("====================================="));
  Serial.println(F("[1] Ligar / Desligar LED"));
  Serial.println(F("[2] Ler Status do Botão Físico"));
  Serial.println(F("[3] Ler Valor do Sensor Analógico"));
  Serial.println(F("[A] Ativar / Pausar Sistema"));
  Serial.println(F("[+] Aumentar Velocidade de Atualização"));
  Serial.println(F("[-] Diminuir Velocidade de Atualização"));
  Serial.println(F("[M] Exibir este Menu Novamente"));
  Serial.println(F("====================================="));
  Serial.print(F("Digite o comando desejado: "));
}

void processarComando(char cmd) {
  // Remove quebras de linha acidentais
  if (cmd == '\n' || cmd == '\r') return; 

  Serial.print(cmd); // Replica o comando digitado
  Serial.println(F("\n-------------------------------------"));

  switch (cmd) {
    case '1':
      digitalWrite(PINO_LED, !digitalRead(PINO_LED));
      Serial.print(F("-> Estado do LED alterado para: "));
      Serial.println(digitalRead(PINO_LED) ? F("LIGADO") : F("DESLIGADO"));
      break;

    case '2':
      Serial.print(F("-> Estado do Botão Físico: "));
      Serial.println(digitalRead(PINO_BOTAO) == LOW ? F("PRESSIONADO") : F("SOLTO"));
      break;

    case '3':
      Serial.print(F("-> Leitura do Sensor Analógico: "));
      Serial.println(analogRead(PINO_SENSOR));
      break;

    case 'A':
    case 'a':
      sistemaAtivo = !sistemaAtivo;
      Serial.print(F("-> Monitoramento Geral: "));
      Serial.println(sistemaAtivo ? F("EXECUTANDO") : F("PAUSADO"));
      break;

    case '+':
      if (velocidadeLeitura > 100) velocidadeLeitura -= 100;
      Serial.print(F("-> Intervalo de atualização reduzido para: "));
      Serial.print(velocidadeLeitura);
      Serial.println(F(" ms (Mais rápido)"));
      break;

    case '-':
      velocidadeLeitura += 100;
      Serial.print(F("-> Intervalo de atualização aumentado para: "));
      Serial.print(velocidadeLeitura);
      Serial.println(F(" ms (Mais lento)"));
      break;

    case 'M':
    case 'm':
      exibirMenu();
      return;

    default:
      Serial.println(F("-> Comando inválido! Digite 'M' para ver as opções."));
      break;
  }
  Serial.print(F("\nPróximo comando: "));
}

